/**
 * One profile. Hold one per signed-in account.
 */
public protocol ClientProtocol: AnyObject, Sendable {
    
    func conversations() throws  -> [Conversation]
    
    /**
     * Open a DM with KT-verified peers (handles). Returns the group id.
     */
    func createDm(handles: [String], title: String?) throws  -> String
    
    func login() throws  -> Profile
    
    /**
     * KT-verify a peer by handle.
     */
    func lookup(handle: String) throws  -> Peer
    
    func messages(groupId: String) throws  -> [Message]
    
    func profile() throws  -> Profile?
    
    func register(handle: String) throws  -> Profile
    
    func send(groupId: String, text: String) throws 
    
    /**
     * Hold the gateway open in the background (reconnecting) and forward
     * every event to `listener`. Requires a login. Idempotent.
     */
    func startGateway(listener: EventListener) 
    
    func stopGateway() 
    
    func sync() throws 
    
}
