        )
        
        case 2: return .loggedIn
        
        case 3: return .conversationCreated(groupId: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .conversationJoined(groupId: try FfiConverterString.read(from: &buf)
        )
        
