        )
        
        case 6: return .messageReceived(groupId: try FfiConverterString.read(from: &buf), epoch: try FfiConverterUInt64.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .epochAdvanced(groupId: try FfiConverterString.read(from: &buf), epoch: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 8: return .gatewayConnected
        
        case 9: return .gatewayDisconnected
        
